-- 号池调度精细控制(2026-09-16 立,深度对标补强 Y,对标竞品 temp-unschedulable 等)。
-- 三列均可空/默认,向后兼容:
--   temp_unschedulable = true → 选路跳过(admin 手动摘除,区别于 isEnabled 永久停用)
--   rate_multiplier → 该 Key 有效权重乘数(NULL = 全局)
--   rpm_override → 账号级 RPM 覆盖(NULL = 沿用分组/全局)
-- 幂等:ADD COLUMN IF NOT EXISTS。

ALTER TABLE "ai_relay_key_pool" ADD COLUMN IF NOT EXISTS "temp_unschedulable" boolean DEFAULT false NOT NULL;
ALTER TABLE "ai_relay_key_pool" ADD COLUMN IF NOT EXISTS "rate_multiplier" numeric(6, 2);
ALTER TABLE "ai_relay_key_pool" ADD COLUMN IF NOT EXISTS "rpm_override" integer;
